@startuml

class EBike {
  + modelName : string
  + weight : float
  + maxSpeed : float
}

class Frame {
  + material : string
  + frameSize : string
}

class DriveSystem {
  + maxTorque : float
  + gearRatio : float
}

class Motor {
  + powerRating : float
  + type : string
}

class Controller {
  + currentState : ControllerState
  + updateStatus() : void
}

class BasicController {}

class AdvancedController {
  + nextMaintenanceDate : date
  + estimateMaintenance() : date
}

class Battery {
  + storedEnergyWh : float
  + capacity : float
}

class Wheel {
  + diameter : float
  + tirePressure : float
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "1" *-- "0..1" Battery
EBike "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
BasicController --|> Controller
AdvancedController --|> Controller
Controller --> Battery : controls
Controller --> DriveSystem : commands

@enduml

